const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (!r || !r.name) continue;
  out.push({ json: {
    repo: r.name,
    full_name: r.full_name,
    default_branch: r.default_branch || 'main',
    archived: !!r.archived,
    fork: !!r.fork,
    language: r.language || null,
    pushed_at: r.pushed_at || null
  }});
}
out.sort((a,b) => a.json.repo.localeCompare(b.json.repo));
return out;

const rows = $input.all().map(i => i.json);
rows.sort((a,b) => (b.locale_count - a.locale_count) || a.repo.localeCompare(b.repo));

const withLocales = rows.filter(r => r.locale_count > 0);
const without = rows.filter(r => r.locale_count === 0);

const all = {};
for (const r of withLocales) for (const l of r.locales) all[l] = (all[l] || 0) + 1;

const lines = [];
lines.push('| Repo | Locale root(s) | # | Locales |');
lines.push('|---|---|---|---|');
for (const r of withLocales) {
  lines.push('| ' + r.repo + ' | ' + r.locale_roots.map(x => x.path + ' (' + x.locales.length + ')').join('<br>') + ' | ' + r.locale_count + ' | ' + r.locales.join(' ') + ' |');
}

const suspicious = withLocales.filter(r => Object.keys(r.matched_by_suffix || {}).length > 0)
  .map(r => ({ repo: r.repo, suffix_matched: r.matched_by_suffix }));

return [{ json: {
  scanned: rows.length,
  repos_with_locale_files: withLocales.length,
  repos_without: without.map(r => ({ repo: r.repo, status: r.http_status, blobs: r.blob_count, truncated: r.tree_truncated })),
  locale_frequency: Object.keys(all).sort((a,b) => (all[b]-all[a]) || a.localeCompare(b)).map(l => l + ':' + all[l]),
  suffix_matches: suspicious,
  markdown: lines.join('\n'),
  detail: withLocales
}}];

const meta = $('Loop Repos').first().json;
const res = $input.first().json || {};
const status = res.statusCode || 0;
const body = res.body || {};
const tree = Array.isArray(body.tree) ? body.tree : [];

const LOCALE_DIR = /^(locales?|i18n|lang|langs|languages|messages|translations?|intl)([-_][a-z0-9]+)?$/i;
const EXT = /\.(json|ts|tsx|js|mjs|cjs|ya?ml|po|pot|mo|properties|xlf|xliff|arb|strings|resx)$/i;
const ISO = new Set(('aa ab ae af ak am an ar as av ay az ba be bg bh bi bm bn bo br bs ca ce ch co cr cs cu cv cy ' +
 'da de dv dz ee el en eo es et eu fa ff fi fj fo fr fy ga gd gl gn gu gv ha he hi ho hr ht hu hy hz ia id ie ig ' +
 'ii ik io is it iu ja jv ka kg ki kj kk kl km kn ko kr ks ku kv kw ky la lb lg li ln lo lt lu lv mg mh mi mk ml ' +
 'mn mr ms mt my na nb nd ne ng nl nn no nr nv ny oc oj om or os pa pi pl ps pt qu rm rn ro ru rw sa sc sd se sg ' +
 'si sk sl sm sn so sq sr ss st su sv sw ta te tg th ti tk tl tn to tr ts tt tw ty ug uk ur uz ve vi vo wa wo xh ' +
 'yi yo za zh zu fil ceb haw kab pst cus').split(/\s+/));

function isLocaleToken(tok) {
  const t = String(tok).toLowerCase();
  const m = t.match(/^([a-z]{2,3})(?:[-_]([a-z]{2,4}))?$/);
  if (!m) return null;
  if (!ISO.has(m[1])) return null;
  return m[2] ? m[1] + '_' + m[2].toUpperCase() : m[1];
}

function parseCandidate(name) {
  let loc = isLocaleToken(name);
  if (loc) return { loc: loc, exact: true };
  const m = String(name).match(/[-_]([A-Za-z]{2,3}(?:[-_][A-Za-z]{2,4})?)$/);
  if (m) {
    loc = isLocaleToken(m[1]);
    if (loc) return { loc: loc, exact: false };
  }
  return null;
}

const found = {};
const loose = {};
const roots = {};
const sampleByLocale = {};

for (const n of tree) {
  if (n.type !== 'blob') continue;
  const p = n.path;
  if (!p) continue;
  if (/(^|\/)(node_modules|dist|build|\.next|vendor|coverage)(\/|$)/i.test(p)) continue;
  const parts = p.split('/');
  let idx = -1;
  for (let i = 0; i < parts.length - 1; i++) {
    if (LOCALE_DIR.test(parts[i])) idx = i;
  }
  if (idx === -1) continue;
  const rest = parts.slice(idx + 1);
  if (!rest.length) continue;
  let cand = rest[0];
  if (rest.length === 1) {
    if (!EXT.test(cand)) continue;
    cand = cand.replace(EXT, '');
  }
  const parsed = parseCandidate(cand);
  if (!parsed) continue;
  const loc = parsed.loc;
  found[loc] = (found[loc] || 0) + 1;
  if (!parsed.exact) loose[loc] = (loose[loc] || 0) + 1;
  const root = parts.slice(0, idx + 1).join('/');
  roots[root] = roots[root] || {};
  roots[root][loc] = true;
  if (!sampleByLocale[loc]) sampleByLocale[loc] = p;
}

const locales = Object.keys(found).sort();
const rootList = Object.keys(roots).sort().map(r => ({ path: r, locales: Object.keys(roots[r]).sort() }));

return [{ json: {
  repo: meta.repo,
  default_branch: meta.default_branch,
  archived: meta.archived,
  pushed_at: meta.pushed_at,
  http_status: status,
  tree_truncated: !!body.truncated,
  blob_count: tree.length,
  locale_roots: rootList,
  locale_count: locales.length,
  locales: locales,
  files_per_locale: found,
  matched_by_suffix: loose,
  sample_en: sampleByLocale['en'] || null
}}];
